//! Replays the golden corpus generated by
//! `electricity/scripts/generate_http_conventions_corpus.py` -- real
//! output from `circuitry.http_conventions`'s own functions (issue
//! #778) -- against this crate's own ports: the proxy rule
//! (`no_proxy`'s exact-IP and `host:port` matching included), strict
//! port parsing, the http(s)-only scheme check, and userinfo/
//! credential redaction. These are Circuitry's own conventions, never
//! a third-party reference's, so cof's own output is the source of
//! truth both engines replay.
//!
//! `Retry-After` parsing (the corpus's own `retry_after_cases`) is
//! replayed by `electricity-vm`'s own
//! `tests/http_conventions_retry_after_corpus.rs` instead:
//! `parse_retry_after_seconds_at` lives in that crate
//! (`electricity_vm::retry`), which this crate has no dependency on
//! (`electricity-vm` depends on `electricity-tools`, never the other
//! way around) -- both test files read the same committed JSON file.
//!
//! The corpus is checked in (`tests/golden/http_conventions_corpus.json`);
//! CI separately regenerates it with Python 3.11 and fails the build if
//! it differs (`.github/workflows/electricity-generated.yml`), so this
//! test only needs to trust the committed file.

use electricity_tools::http::http_url::urlsplit;
use electricity_tools::http_client::resolve_proxy_checked_with_port;
use electricity_tools::http_conventions::{
    check_scheme, redact_proxy_value, redact_url, strict_port,
};

fn load_corpus() -> serde_json::Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden/http_conventions_corpus.json");
    let text = std::fs::read_to_string(path).expect("golden/http_conventions_corpus.json exists");
    serde_json::from_str(&text).expect("valid JSON")
}

fn check_url(url: &str) -> Result<(), String> {
    let split = urlsplit(url, "");
    check_scheme(&split.scheme, url, &["http", "https"])?;
    strict_port(&split.netloc, url)?;
    Ok(())
}

#[test]
fn scheme_detection_cases_match_cof() {
    let corpus = load_corpus();
    for case in corpus["scheme_detection_cases"].as_array().unwrap() {
        let url = case["url"].as_str().unwrap();
        let expected = case["error"].as_str();
        let actual = check_url(url).err();
        assert_eq!(actual.as_deref(), expected, "case: {case:?}");
    }
}

#[test]
fn strict_port_cases_match_cof() {
    let corpus = load_corpus();
    for case in corpus["strict_port_cases"].as_array().unwrap() {
        let url = case["url"].as_str().unwrap();
        let expected = case["error"].as_str();
        let netloc = urlsplit(url, "").netloc;
        let actual = strict_port(&netloc, url).err();
        assert_eq!(actual.as_deref(), expected, "case: {case:?}");
    }
}

#[test]
fn redaction_cases_match_cof() {
    let corpus = load_corpus();
    for case in corpus["redaction_cases"].as_array().unwrap() {
        let url = case["url"].as_str().unwrap();
        let expected = case["redacted"].as_str().unwrap();
        assert_eq!(redact_url(url), expected, "case: {case:?}");
    }
}

#[test]
fn proxy_redaction_cases_match_cof() {
    let corpus = load_corpus();
    for case in corpus["proxy_redaction_cases"].as_array().unwrap() {
        let value = case["value"].as_str().unwrap();
        let expected = case["redacted"].as_str().unwrap();
        assert_eq!(redact_proxy_value(value), expected, "case: {case:?}");
    }
}

#[test]
fn proxy_cases_match_cof() {
    let corpus = load_corpus();
    for case in corpus["proxy_cases"].as_array().unwrap() {
        let env: Vec<(String, String)> = case["env"]
            .as_array()
            .unwrap()
            .iter()
            .map(|pair| {
                let pair = pair.as_array().unwrap();
                (
                    pair[0].as_str().unwrap().to_string(),
                    pair[1].as_str().unwrap().to_string(),
                )
            })
            .collect();
        let scheme = case["scheme"].as_str().unwrap();
        let host = case["host"].as_str().unwrap();
        let port = case["port"].as_u64().map(|p| p as u16);
        let result = resolve_proxy_checked_with_port(scheme, host, port, &env);
        if let Some(expected_ok) = case["result"].get("ok") {
            assert_eq!(
                result.unwrap(),
                expected_ok.as_str().map(str::to_string),
                "case: {case:?}"
            );
        } else if let Some(expected_err) = case["result"].get("error") {
            assert_eq!(
                result.unwrap_err(),
                expected_err.as_str().unwrap(),
                "case: {case:?}"
            );
        } else {
            panic!("case result has neither ok nor error: {case:?}");
        }
    }
}
